INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1528, 155, 1, 'النوع التاسع: وِرْدُ الحَوْلَقة', 0, '(ص339)', '', '', 'النوع التاسع ورد الحولقة', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1139, 155, 2, 'الحولقة: كلمة منحوتة من جملة «لا حولَ ولا قوةَ إلا بالله».', 0, 'النوع التاسع: وِرْدُ الحَوْلَقة. (ص339)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1140, 155, 3, 'قال الإمام الطحاوي رحمه الله في تفسير «لا حَوْلَ ولا قُوَّةَ إلا بالله»: «نقول: لا حِيلةَ لأحدٍ، ولا تَحَوُّلَ لأحدٍ، ولا حركةَ لأحدٍ عن معصية الله إلا بمعونة الله، ولا قوة لأحد على إقامة طاعة الله والثبات عليها، إلا بتوفيق الله، وكل شيء يجري بمشيئة الله تعالى وعلمِهِ، وقضائه وقدره، غَلَبَتْ مشيئتُهُ المشيئاتِ كلَّها، وعكست إرادتُهُ الإراداتِ كلَّها، وغلبَ قضاؤه الحِيَلَ كلَّها».اهـ.', 0, 'النوع التاسع: وِرْدُ الحَوْلَقة. (ص339)', '', '', 'قال الإمام الطحاوي رحمه الله في تفسير «لا حول ولا قوة إلا بالله» «نقول لا حيلة لأحد ولا تحول لأحد ولا حركة لأحد عن معصية الله إلا بمعونة الله ولا قوة لأحد على إقامة طاعة الله والثبات عليها إلا بتوفيق الله وكل شيء يجري بمشيئة الله تعالى وعلمه وقضائه وقدره غلبت مشيئته المشيئات كلها وعكست إرادته الإرادات كلها وغلب قضاؤه الحيل كلها» اه', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1529, 155, 4, 'وقال شيخ الإسلام ابن تيمية رحمه الله: «فلفظ الحول يتناول كل تحول من حال إلى حال. والقوة هي القدرة على ذلك التحوُّل، فدلَّت هذه الكلمة العظيمة على أنه ليس للعالم العلوي والسفلي حركةٌ وتحول من حال إلى حال ولا قدرة على ذلك إلا بالله، ومن الناس من يفسر ذلك بمعنًى خاصٍّ فيقول: لا حول من معصيته إلا بعصمته، ولا قوة على طاعته إلا بمعونته، والصوابُ الذي عليه الجمهور هو التفسير الأول، وهو الذي يدل عليه اللفظ.
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1530, 156, 1, 'فضائل الحولقة:', 0, '(ص341)', '', '', 'فضائل الحولقة', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1148, 156, 2, 'عن أبي هريرة رضي الله عنه أن رسول الله ﷺ، قال: «ألا أعلمك -أو قال: ألا أدُلُّكَ- على كلمةٍ من تحتِ العرشِ من كَنْزِ الجنة؟ تقول: لا حَوْلَ وَلَا قُوَّةَ إلا بالله، فيقول اللهُ عَزَّ وَجَلَّ: أَسْلَمَ عبدي، واسْتَسْلَمَ».', 0, 'فضائل الحولقة. (ص341)', '', '', 'عن أبي هريرة رضي الله عنه أن رسول الله قال «ألا أعلمك -أو قال ألا أدلك- على كلمة من تحت العرش من كنز الجنة تقول لا حول ولا قوة إلا بالله فيقول الله عز وجل أسلم عبدي واستسلم»', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1149, 156, 3, 'وعنه أيضًا رضي الله عنه، أنَّ النبيَّ ﷺ قال: «أَكْثِرُوا مِنْ قَوْلِ: لا حَوْلَ ولا قُوَّةَ إلَّا بالله، فإنها كَنْزٌ مِنْ كُنُوزِ الْجَنَّة».', 0, 'فضائل الحولقة. (ص341)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1150, 156, 4, 'وعن أبي أيوبَ الأنصاريِّ رضي الله عنه، أن النبي ﷺ ليلةَ أُسْرِيَ به مرَّ على إبراهيم -على نبينا وعليه الصلاة والسلام- فقال: «يا محمد مُر أُمَّتَك أن يُكثِروا من غِراس الجنة، قال: وما غراس الجنة؟ قال: لا حول ولا قوة إلا بالله».', 0, 'فضائل الحولقة. (ص341–342)', '', '', 'وعن أبي أيوب الأنصاري رضي الله عنه أن النبي ليلة أسري به مر على إبراهيم -على نبينا وعليه الصلاة والسلام- فقال «يا محمد مر أمتك أن يكثروا من غراس الجنة قال وما غراس الجنة قال لا حول ولا قوة إلا بالله»', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1152, 156, 5, 'وعن قيس بن سعد بن عبادة أن أباه دفعه إلى النبي ﷺ يخدمه قال: فمرَّ بي النبي ﷺ وقد صَلَّيْتُ فضربني برِجْلِهِ، وقال: «ألا أَدُلُّكَ على بابٍ من أبواب الجنة؟» قلت: بلى، قال: «لا حول ولا قوة إلا بالله».', 0, 'فضائل الحولقة. (ص342)', '', '', 'وعن قيس بن سعد بن عبادة أن أباه دفعه إلى النبي يخدمه قال فمر بي النبي وقد صليت فضربني برجله وقال «ألا أدلك على باب من أبواب الجنة » قلت بلى قال «لا حول ولا قوة إلا بالله»', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1531, 157, 1, 'تنبيهان:', 0, '(ص342)', '', '', 'تنبيهان', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1154, 157, 2, 'يخطئ بعض الناس حين يستعمل الحولقة كلمةَ استرجاعٍ، ولا يَفْهَمُ منها معنى الاستعانة، قال شيخ الإسلام ابن تيمية رحمه الله: «... هذه الكلمة هي كلمة استعانة لا كلمة استرجاع، وكثير من الناس يقولها عند المصائب بمنزلة الاسترجاع، ويقولها جَزَعًا لا صبرًا».اهـ.', 0, 'تنبيهان. (ص342)', '', '', 'يخطئ بعض الناس حين يستعمل الحولقة كلمة استرجاع ولا يفهم منها معنى الاستعانة قال شيخ الإسلام ابن تيمية رحمه الله « هذه الكلمة هي كلمة استعانة لا كلمة استرجاع وكثير من الناس يقولها عند المصائب بمنزلة الاسترجاع ويقولها جزعا لا صبرا» اه', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1155, 157, 3, 'وبسبب غفلة بعض الناس عن معناها يختصرونها بقولهم: «لا حَوْلِ الله»، وهذا إخلال بلفظها ومعناها.', 0, 'تنبيهان. (ص343)', '', '', 'وبسبب غفلة بعض الناس عن معناها يختصرونها بقولهم «لا حول الله» وهذا إخلال بلفظها ومعناها', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1532, 168, 1, 'النوع العاشر: وِرْدُ الدعاء بالعافية', 0, '(ص344)', '', '', 'النوع العاشر ورد الدعاء بالعافية', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1533, 168, 2, 'العافية هي دِفاعُ اللهِ عن العبد.', 0, 'النوع العاشر: وِرْدُ الدعاء بالعافية. (ص344)', '', '', 'العافية هي دفاع الله عن العبد', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1534, 168, 3, 'والعافية في الدنيا: دفاع الله عن العبد، جميعَ الأسقام والبلايا، وكل ما يكرهه ويشينه.', 0, 'النوع العاشر: وِرْدُ الدعاء بالعافية. (ص344)', '', '', 'والعافية في الدنيا دفاع الله عن العبد جميع الأسقام والبلايا وكل ما يكرهه ويشينه', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1535, 168, 4, 'والعافية في الآخرة: دفاع الله عن العبد جميعَ أهوالِ الآخرة وأفزاعِها، وتمامها: النجاة من النار، والفوز بالجنة.', 0, 'النوع العاشر: وِرْدُ الدعاء بالعافية. (ص344)', '', '', 'والعافية في الآخرة دفاع الله عن العبد جميع أهوال الآخرة وأفزاعها وتمامها النجاة من النار والفوز بالجنة', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1536, 168, 5, 'إن الدعوة بالعافية جامعة كافية، وافية شافية، فهي مِفْتاحُ النعيم، وباب الطيبات، وكَنْزُ السعداء.', 0, 'النوع العاشر: وِرْدُ الدعاء بالعافية. (ص344)', '', '', 'إن الدعوة بالعافية جامعة كافية وافية شافية فهي مفتاح النعيم وباب الطيبات وكنز السعداء', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1537, 168, 6, 'والعافية المطلقة أَجَلُّ النِّعَمِ على الإطلاق، لأنها لتحصيل المقاصد وافيةٌ ولدفع البلايا كافيةٌ.', 0, 'النوع العاشر: وِرْدُ الدعاء بالعافية. (ص344)', '', '', 'والعافية المطلقة أجل النعم على الإطلاق لأنها لتحصيل المقاصد وافية ولدفع البلايا كافية', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1538, 168, 7, 'وَأَوْلَى ما يُسأل فيه العافية: العافية في الدين، قال ﷺ في دعائه: «ولا تجعَلْ مُصِيبَتَنَا في دِينِنا»، وقال ﷺ: «اللهم أَصْلِحْ لي ديني الذي هو عِصْمَةُ أمري».', 0, 'النوع العاشر: وِرْدُ الدعاء بالعافية. (ص345)', '', '', 'وأولى ما يسأل فيه العافية العافية في الدين قال في دعائه «ولا تجعل مصيبتنا في ديننا» وقال «اللهم أصلح لي ديني الذي هو عصمة أمري»', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1539, 168, 8, 'لا تأسَ من دُنيا على فائتٍ
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1540, 168, 9, 'ومما يدلُّ على أن الدعاء بالعافية لا يساويه شيء من الأدعية، ولا يقومُ مقامَه شيء من الكلام الذي يُدْعَى به ذو الجلال والإكرام، وأن من أُوتي العافيةَ في الدنيا والآخرة؛ فقد أُوتي الخيرَ بحذافيره، وأن العافية لا يعدلها شيء:', 0, 'النوع العاشر: وِرْدُ الدعاء بالعافية. (ص345)', '', '', 'ومما يدل على أن الدعاء بالعافية لا يساويه شيء من الأدعية ولا يقوم مقامه شيء من الكلام الذي يدعى به ذو الجلال والإكرام وأن من أوتي العافية في الدنيا والآخرة فقد أوتي الخير بحذافيره وأن العافية لا يعدلها شيء', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1541, 168, 10, 'أن العباسَ بنَ عبدِ المُطَّلِب رضي الله عنه، قال: قلتُ: يا رسولَ الله، عَلِّمني شيئًا أسأله اللهَ عَزَّ وَجَلَّ، قال: «سَلِ اللهَ العافيةَ»، فمكثتُ أيامًا، ثمَّ جِئتُ، فقلتُ: يا رسولَ اللهِ، علمني شيئًا أَسألُه اللهَ، فقال لي: «يا عبَّاسُ، يا عَمَّ رسولِ الله، سَلِ اللهَ العافيةَ، في الدُّنيا والآخرة».', 0, 'النوع العاشر: وِرْدُ الدعاء بالعافية. (ص345–346)', '', '', 'أن العباس بن عبد المطلب رضي الله عنه قال قلت يا رسول الله علمني شيئا أسأله الله عز وجل قال «سل الله العافية» فمكثت أياما ثم جئت فقلت يا رسول الله علمني شيئا أسأله الله فقال لي «يا عباس يا عم رسول الله سل الله العافية في الدنيا والآخرة»', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1542, 168, 11, 'وعن ابن عباس رضي الله عنهما أن النبي ﷺ قال لعَمِّه العباس رضي الله عنه: «يا عَمِّ: أَكْثِرِ الدعاءَ بالعافية».', 0, 'النوع العاشر: وِرْدُ الدعاء بالعافية. (ص346)', '', '', 'وعن ابن عباس رضي الله عنهما أن النبي قال لعمه العباس رضي الله عنه «يا عم أكثر الدعاء بالعافية»', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1543, 168, 12, 'قال الإمام الكبير محمد بن محمد بن علي بن يوسف الجزري (ت: ٨٣٣ هـ) رحمه الله في خاتمة كتابه «عُدَّة الحصن الحصين من كلام سيد المرسلين ﷺ» مُعَلِّقًا على الحديثين الآنِفَي الذكر: «فَلْيَنْظُرِ العاقلُ مِقْدَارَ هذه الكلمة التي اختارها رسولُ الله ﷺ لعمِّه مِن دون الكَلِم، وَلْيُؤْمِنْ بأنه ﷺ أُعْطِيَ جوامعَ الكلم، واختُصِرَتْ له الحِكَمُ، فإنَّ مَن أُعطِي العافيةَ فاز بما يرجوه ويحبه قلبًا وقالَبًا ودينًا، وَوُقِيَ ما يخافه في الدارين علمًا يقينًا، فلقد تواتر عنه ﷺ دعاؤه بالعافية، وورد عنه ﷺ لفظًا ومعنًى من نحو خمسين طريقًا. هذا وقد غُفر له ما تقدم من ذنبه وما تأخر، وهو المعصومُ على الإطلاق حقيقةً، فكيف بنا ونحن غَرَضٌ لسهام القَدَرِ وغَرَضٌ بين النَّفْسِ والشيطان والهوى، كما وَرَدَ في الخبر: (اللَّهُمَّ إنا نَسْأَلُكَ العَافِيَةَ في الدُّنْيَا وَالآخِرَةِ)».اهـ.', 0, 'النوع العاشر: وِرْدُ الدعاء بالعافية. (ص346–347)', '', '', 'قال الإمام الكبير محمد بن محمد بن علي بن يوسف الجزري ت ٨٣٣ ه رحمه الله في خاتمة كتابه «عدة الحصن الحصين من كلام سيد المرسلين » معلقا على الحديثين الآنفي الذكر «فلينظر العاقل مقدار هذه الكلمة التي اختارها رسول الله لعمه من دون الكلم وليؤمن بأنه أعطي جوامع الكلم واختصرت له الحكم فإن من أعطي العافية فاز بما يرجوه ويحبه قلبا وقالبا ودينا ووقي ما يخافه في الدارين علما يقينا فلقد تواتر عنه دعاؤه بالعافية وورد عنه لفظا ومعنى من نحو خمسين طريقا هذا وقد غفر له ما تقدم من ذنبه وما تأخر وهو المعصوم على الإطلاق حقيقة فكيف بنا ونحن غرض لسهام القدر وغرض بين النفس والشيطان والهوى كما ورد في الخبر اللهم إنا نسألك العافية في الدنيا والآخرة » اه', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1544, 168, 13, 'وقال الإمام الشوكاني رحمه الله: «وقد كان رسول الله ﷺ يُنزِلُ عمَّه العباسَ منزلةَ أبيه، ويرى له من الحقِّ ما يراه الولدُ لوالده، ففي تخصيصه بهذا الدعاء وقَصْرِه على مجرد الدعاء بالعافية تحريكٌ لِهِمَمِ الراغبين على ملازمته، وأن يجعلوه من أعظم ما يتوسلون به إلى ربهم سبحانه وتعالى، ويستدفعون به كل ما يُهِمُّهم، ثم كلَّمه ﷺ بقوله: «سَلِ اللهَ العافيةَ في الدنيا والآخرة»، فكان هذا الدعاء من هذه الحيثية قد صار عُدَّةً لدفع كلِّ ضُرٍّ وجَلْبِ كلِّ خيرٍ. اللهم إنا نسألك العافيةَ في الدنيا والآخرة يا أرحمَ الراحمين آمين».', 0, 'النوع العاشر: وِرْدُ الدعاء بالعافية. (ص347)', '', '', 'وقال الإمام الشوكاني رحمه الله «وقد كان رسول الله ينزل عمه العباس منزلة أبيه ويرى له من الحق ما يراه الولد لوالده ففي تخصيصه بهذا الدعاء وقصره على مجرد الدعاء بالعافية تحريك لهمم الراغبين على ملازمته وأن يجعلوه من أعظم ما يتوسلون به إلى ربهم سبحانه وتعالى ويستدفعون به كل ما يهمهم ثم كلمه بقوله «سل الله العافية في الدنيا والآخرة» فكان هذا الدعاء من هذه الحيثية قد صار عدة لدفع كل ضر وجلب كل خير اللهم إنا نسألك العافية في الدنيا والآخرة يا أرحم الراحمين آمين»', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1545, 168, 14, 'وعن أنس رضي الله عنه قال: أتى النبيَّ ﷺ رجلٌ، فقال: يا رسولَ الله، أيُّ الدعاء أفضل؟ قال: «سَلِ اللهَ العفوَ والعافيةَ في الدنيا والآخرة».
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1546, 168, 15, 'قال الإمام الشوكاني رحمه الله: «ففي هذا الحديث التصريحُ بأن الدعاء بالعافية أفضل الدعاء، ولا سيَّما بعد تكريره للسائل في ثلاثة أيام حين يأتيه للسؤال عن أفضل الدعاء، فأفاد هذا أن الدعاء بالعافية أفضل من غيره من الأدعية، مع ما قدمنا من اشتماله على جَلْبِ كُلِّ نفعٍ، ودفعِ كُلِّ ضُرٍّ، ثُمَّ في قوله في آخر هذا الحديث: «فإذا أُعْطِيتَ العافيةَ في الدنيا، وأُعْطِيتَها في الآخرة؛ فقد أفلحت» دليلٌ ظاهر واضح بأن الدعاء بالعافية يشمل أمورَ الدنيا والآخرة؛ لأنه قال هذه المقالة بعد أن قال له: «سَل ربك العافية» ثلاث مرات، فكان ذلك كالبيان لعموم بركة هذه الدعوة بالعافية لمصالح الدنيا والآخرة، ثم رتَّب على ذلك الفلاح الذي هو المقصد الأسنى والمطلوب الأكبر».اهـ.', 0, 'النوع العاشر: وِرْدُ الدعاء بالعافية. (ص348–349)', '', '', 'قال الإمام الشوكاني رحمه الله «ففي هذا الحديث التصريح بأن الدعاء بالعافية أفضل الدعاء ولا سيما بعد تكريره للسائل في ثلاثة أيام حين يأتيه للسؤال عن أفضل الدعاء فأفاد هذا أن الدعاء بالعافية أفضل من غيره من الأدعية مع ما قدمنا من اشتماله على جلب كل نفع ودفع كل ضر ثم في قوله في آخر هذا الحديث «فإذا أعطيت العافية في الدنيا وأعطيتها في الآخرة فقد أفلحت» دليل ظاهر واضح بأن الدعاء بالعافية يشمل أمور الدنيا والآخرة لأنه قال هذه المقالة بعد أن قال له «سل ربك العافية» ثلاث مرات فكان ذلك كالبيان لعموم بركة هذه الدعوة بالعافية لمصالح الدنيا والآخرة ثم رتب على ذلك الفلاح الذي هو المقصد الأسنى والمطلوب الأكبر» اه', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1547, 168, 16, 'وعن أبي هريرة رضي الله عنه قال: سَمِعْتُ أَبَا بَكْرٍ -رِضْوانُ اللهِ عَلَيْهِ- عَلَى هذا المنبرِ يقُولُ: سَمِعْتُ رَسُولَ اللهِ ﷺ هَذَا الْيَوْمَ عَامَ أَوَّلَ يقول، ثُمَّ اسْتَعْبَرَ أَبو بَكْرٍ -رِضْوانُ اللهِ عَلَيْهِ- فَبَكَى، ثُمَّ قَالَ: سَمِعْتُ رَسُولَ الله ﷺ يَقُولُ: «لَن تُؤْتَوا شَيئًا بَعدَ كَلِمَةِ الإِخْلَاصِ مِثْلَ العَافِيَةِ، فَسَلُوا اللهَ العافيةَ».', 0, 'النوع العاشر: وِرْدُ الدعاء بالعافية. (ص349)', '', '', 'وعن أبي هريرة رضي الله عنه قال سمعت أبا بكر -رضوان الله عليه- على هذا المنبر يقول سمعت رسول الله هذا اليوم عام أول يقول ثم استعبر أبو بكر -رضوان الله عليه- فبكى ثم قال سمعت رسول الله يقول «لن تؤتوا شيئا بعد كلمة الإخلاص مثل العافية فسلوا الله العافية»', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1548, 168, 17, 'وعن أبي بكر الصديق رضي الله عنه أن رسول الله ﷺ قَالَ: «سَلُوا اللهَ العفوَ والعافيةَ؛ فإنَّ أحدًا لم يُعْطَ بعد اليقين خيرًا مِنَ العافية».', 0, 'النوع العاشر: وِرْدُ الدعاء بالعافية. (ص349)', '', '', 'وعن أبي بكر الصديق رضي الله عنه أن رسول الله قال «سلوا الله العفو والعافية فإن أحدا لم يعط بعد اليقين خيرا من العافية»', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1549, 168, 18, 'وعن أبي هريرة رضي الله عنه قال: قال رسول الله ﷺ: «مَا مِن دَعْوَةٍ يَدْعُو بها العبدُ أَفْضَلُ مِن: اللَّهُمَّ إِنِّي أسألُكَ المُعافاةَ في الدُّنيا والآخرة».', 0, 'النوع العاشر: وِرْدُ الدعاء بالعافية. (ص350)', '', '', 'وعن أبي هريرة رضي الله عنه قال قال رسول الله «ما من دعوة يدعو بها العبد أفضل من اللهم إني أسألك المعافاة في الدنيا والآخرة»', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1550, 168, 19, 'وَرُوِيَ عن ابنِ عُمَرَ رضي الله عنهما قال: قال رسول الله ﷺ: «مَنْ فُتِحَ لَه مِنْكُم بَابُ الدُّعَاءِ؛ فُتِحَتْ له أبوابُ الرَّحْمَةِ، وما سُئِلَ اللهُ شَيْئًا: أَحَبَّ إِلَيهِ مِنْ أَنْ يُسْأَلَ العافيةَ» الحديثَ.', 0, 'النوع العاشر: وِرْدُ الدعاء بالعافية. (ص350)', '', '', 'وروي عن ابن عمر رضي الله عنهما قال قال رسول الله «من فتح له منكم باب الدعاء فتحت له أبواب الرحمة وما سئل الله شيئا أحب إليه من أن يسأل العافية» الحديث', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1551, 168, 20, 'قال منصورٌ الفقيهُ رحمه الله:
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1552, 169, 1, 'وِرْدُ الدُّعاءِ بالعافية', 0, '(ص351)', '', '', 'ورد الدعاء بالعافية', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1553, 169, 2, '﴿ رَبَّنَآ ءَاتِنَا فِي ٱلدُّنۡيَا حَسَنَةٗ وَفِي ٱلۡأٓخِرَةِ حَسَنَةٗ وَقِنَا عَذَابَ ٱلنَّارِ ﴾', 1, 'وِرْدُ الدُّعاءِ بالعافية. [البقرة: ٢٠١]. (ص351)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1554, 169, 3, 'اللهم إني أسألك العافية.', 1, 'وِرْدُ الدُّعاءِ بالعافية. (ص351)', '', '', 'اللهم إني أسألك العافية', '', '');
