INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1556, 169, 5, 'اللهم إني أسألُكَ العافيةَ في الدنيا والآخرة.', 1, 'وِرْدُ الدُّعاءِ بالعافية. (ص351)', '', '', 'اللهم إني أسألك العافية في الدنيا والآخرة', '', '');
