INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1558, 169, 7, 'اللهم إني أسألك المعافاةَ في الدنيا والآخرة.', 1, 'وِرْدُ الدُّعاءِ بالعافية. (ص351)', '', '', 'اللهم إني أسألك المعافاة في الدنيا والآخرة', '', '');
