INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1560, 169, 9, 'اللهم إني أسألك العفو والعافية في الدنيا والآخرة.', 1, 'وِرْدُ الدُّعاءِ بالعافية. (ص351)', '', '', 'اللهم إني أسألك العفو والعافية في الدنيا والآخرة', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1561, 169, 10, 'اللهم إني أسألك اليقينَ والعافية.', 1, 'وِرْدُ الدُّعاءِ بالعافية. (ص352)', '', '', 'اللهم إني أسألك اليقين والعافية', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1562, 169, 11, 'اللهم إني أسألك اليقين والمعافاة.', 1, 'وِرْدُ الدُّعاءِ بالعافية. (ص352)', '', '', 'اللهم إني أسألك اليقين والمعافاة', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1563, 169, 12, 'اللهم أحسن عافيتنا في الأمور كلها، وَأَجِرْنَا مِنْ خِزْيِ الدُّنيا وعذابِ الآخرة.', 1, 'وِرْدُ الدُّعاءِ بالعافية. (ص352)', '', '', 'اللهم أحسن عافيتنا في الأمور كلها وأجرنا من خزي الدنيا وعذاب الآخرة', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1564, 169, 13, 'اللهم عافِني من شرِّ سمعي وبصري، ولساني وقلبي، وشرِّ مَنِيِّي.', 1, 'وِرْدُ الدُّعاءِ بالعافية. (ص352)', '', '', 'اللهم عافني من شر سمعي وبصري ولساني وقلبي وشر منيي', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1565, 169, 14, 'اللهم اغفر لنا وارحمنا، وآتنا في الدنيا حسنةً، وفي الآخرة حسنةً، وقِنا عذابَ النار.', 1, 'وِرْدُ الدُّعاءِ بالعافية. (ص352)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1566, 171, 1, 'النوع الحادي عشر: وِرْدُ الحَسْبَلة', 0, '(ص353)', '', '', 'النوع الحادي عشر ورد الحسبلة', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1567, 171, 2, 'الحسبلة: كلمة منحوتة من قولك: «حَسْبِيَ اللهُ وَنِعْمَ الوكيل» التي هي إعلان أنك متوكل على الله وحده، وأنه كافيك ووكيلك الذي يُغنيك عمن سواه، ولا يُغني عنه سواه، وفيها ثناءٌ على الله تبارك وتعالى الذي تعتصمُ به، وتلجأ إليه، وتفوِّضُ أمرَكَ كُلَّه إليه، ولا تحتاج معه إلى أحد.', 0, 'النوع الحادي عشر: وِرْدُ الحَسْبَلة. (ص353)', '', '', 'الحسبلة كلمة منحوتة من قولك «حسبي الله ونعم الوكيل» التي هي إعلان أنك متوكل على الله وحده وأنه كافيك ووكيلك الذي يغنيك عمن سواه ولا يغني عنه سواه وفيها ثناء على الله تبارك وتعالى الذي تعتصم به وتلجأ إليه وتفوض أمرك كله إليه ولا تحتاج معه إلى أحد', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1568, 171, 3, 'روى البخاري بسنده إلى ابن عباس رضي الله عنهما قال: ﴿ حَسۡبُنَا ٱللَّهُ وَنِعۡمَ ٱلۡوَكِيلُ ﴾ [آل عمران: ١٧٣] قالها إبراهيمُ عليه السلام حين أُلقي في النار، وقالها محمدٌ ﷺ حين قالوا: ﴿ إِنَّ ٱلنَّاسَ قَدۡ جَمَعُواْ لَكُمۡ فَٱخۡشَوۡهُمۡ فَزَادَهُمۡ إِيمَٰنٗا وَقَالُواْ حَسۡبُنَا ٱللَّهُ وَنِعۡمَ ٱلۡوَكِيلُ ﴾ [آل عمران: ١٧٣].', 0, 'النوع الحادي عشر: وِرْدُ الحَسْبَلة. (ص353)', '', '', 'روى البخاري بسنده إلى ابن عباس رضي الله عنهما قال ﴿ حسۡبنا ٱلله ونعۡم ٱلۡوكيل ﴾ آل عمران ١٧٣ قالها إبراهيم عليه السلام حين ألقي في النار وقالها محمد حين قالوا ﴿ إن ٱلناس قدۡ جمعوا لكمۡ فٱخۡشوۡهمۡ فزادهمۡ إيمنا وقالوا حسۡبنا ٱلله ونعۡم ٱلۡوكيل ﴾ آل عمران ١٧٣', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1569, 171, 4, 'وعنه رضي الله عنه قال: «كان آخِرَ قولِ إبراهيمَ حِينَ أُلْقِيَ في النَّارِ: حَسْبِيَ اللهُ وَنِعْمَ الْوَكِيلُ».', 0, 'النوع الحادي عشر: وِرْدُ الحَسْبَلة. (ص353)', '', '', 'وعنه رضي الله عنه قال «كان آخر قول إبراهيم حين ألقي في النار حسبي الله ونعم الوكيل»', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1570, 171, 5, 'وعن أبي الدرداء رضي الله عنه قال: «من قال إذا أصبح، وإذا أمسى: ﴿ حَسۡبِيَ ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَۖ عَلَيۡهِ تَوَكَّلۡتُۖ وَهُوَ رَبُّ ٱلۡعَرۡشِ ٱلۡعَظِيمِ ﴾ [التوبة: ١٢٩] سبعَ مراتٍ؛ كفاه اللهُ ما أَهَمَّه».', 0, 'النوع الحادي عشر: وِرْدُ الحَسْبَلة. (ص354)', '', '', 'وعن أبي الدرداء رضي الله عنه قال «من قال إذا أصبح وإذا أمسى ﴿ حسۡبي ٱلله لا إله إلا هوۖ عليۡه توكلۡتۖ وهو رب ٱلۡعرۡش ٱلۡعظيم ﴾ التوبة ١٢٩ سبع مرات كفاه الله ما أهمه»', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1571, 171, 6, 'وتنشأ حالة المؤمن حين يقول: «حسبي الله ونعم الوكيل» في موضعها الملائم، مِن تَوَكُّلِه على الله واستعانته به، وهي حال تنشأ «عن معرفة القلب بالله، والإيمانِ بتفرده بالخلق والتدبير، والضر والنفع، والعطاء والمنع، وأنه ما شاء كان، وإن لم يشأ الناس، وما لم يشأ لم يكن، وإن شاءه الناسُ، فيُوجِبُ له هذا اعتمادًا عليه، وتفويضًا إليه، وطمأنينةً به، وثقةً به، ويقينًا بكفايته لما تَوَكَّلَ عليه فيه، وأنه مَلِيٌّ به، ولا يكون إلا بمشيئته، شاءه الناسُ أم أَبَوْهُ.', 0, 'النوع الحادي عشر: وِرْدُ الحَسْبَلة. (ص354)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1572, 171, 7, 'فتشبه حالتُه حالةَ الطفلِ مع أبويه فيما يَنُوبُهُ من رغبةٍ ورهبةٍ هما مَلِيَّان بهما، فانظرْ في تجرد قلبه عن الالتفات إلى غير أبويه، وحبس هَمِّه على إنزال ما ينوبه بهما، فهذه حالُ المتوكِّل، ومن كان هكذا مع الله، فالله كافِيه ولا بُدَّ، قال تعالى: ﴿ وَمَن يَتَوَكَّلۡ عَلَى ٱللَّهِ فَهُوَ حَسۡبُهُۥٓ ﴾ [الطلاق: ٣] أي: كافيه، و«الحَسْبُ»: الكافي، فإن كان -مع هذا- من أهل التقوى كانت له العاقبةُ الحميدة».اهـ.', 0, 'النوع الحادي عشر: وِرْدُ الحَسْبَلة. (ص354–355)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1573, 171, 8, 'إنَّ العبدَ إذا أخذ بما أمكنه من الأسباب المأمور بها لتحصيل مقصوده، ومع ذلك لم يُحَصِّلْه؛ فحينئذٍ تُعَدُّ (الحسبلة) أفضلَ وسائلِ الالتجاء إلى الله تعالى والتوكلِ عليه.', 0, 'النوع الحادي عشر: وِرْدُ الحَسْبَلة. (ص355)', '', '', 'إن العبد إذا أخذ بما أمكنه من الأسباب المأمور بها لتحصيل مقصوده ومع ذلك لم يحصله فحينئذ تعد الحسبلة أفضل وسائل الالتجاء إلى الله تعالى والتوكل عليه', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1574, 171, 9, 'وقوله تعالى: ﴿ وَمَن يَتَوَكَّلۡ عَلَى ٱللَّهِ فَهُوَ حَسۡبُهُۥٓ ﴾ [الطلاق: ٣] معناه: كافيه أمورَ دينه ودنياه، والحسيب: الكافي، والله عَزَّ وَجَلَّ كافي عبادِه؛ لأنه رازقُهم وحافظهم ومُصْلِحُ شؤونهم الذي يكفي بمعونته عن غيره، ويُستغنَى به عَمَّن سواه، قال تعالى: ﴿ أَلَيۡسَ ٱللَّهُ بِكَافٍ عَبۡدَهُۥۖ وَيُخَوِّفُونَكَ بِٱلَّذِينَ مِن دُونِهِۦ ﴾ [الزمر: ٣٦]، وقال تعالى: ﴿ وَٱللَّهُ عَلَىٰ كُلِّ شَيۡءٖ وَكِيلٌ ﴾ [هود: ١٢]، والوكيل: الكافي الكفيل، وهو عامٌّ وخاصٌّ؛ أَمَّا العامُّ: فهو المتكَفِّلُ بأرزاقِ جميع المخلوقات وأقواتها، القائم بتدبير شؤون الكائنات وتصريف أمورها. وأَمَّا الخاصُّ بعباده المؤمنين به المتوكلين عليه، ففي قوله تعالى: ﴿ وَتَوَكَّلۡ عَلَى ٱللَّهِۚ وَكَفَىٰ بِٱللَّهِ وَكِيلًا ﴾ [النساء: ٨١]، أي: نِعْمَ الكافي لِمَنِ التجأَ إليه، والحافظ لِمَنِ اعتصمَ به، وهو المراد في قول المؤمنين: ﴿ حَسۡبُنَا ٱللَّهُ وَنِعۡمَ ٱلۡوَكِيلُ ﴾ [آل عمران: ١٧٣].', 0, 'النوع الحادي عشر: وِرْدُ الحَسْبَلة. (ص355–356)', '', '', 'وقوله تعالى ﴿ ومن يتوكلۡ على ٱلله فهو حسۡبهۥ ﴾ الطلاق ٣ معناه كافيه أمور دينه ودنياه والحسيب الكافي والله عز وجل كافي عباده لأنه رازقهم وحافظهم ومصلح شؤونهم الذي يكفي بمعونته عن غيره ويستغنى به عمن سواه قال تعالى ﴿ أليۡس ٱلله بكاف عبۡدهۥۖ ويخوفونك بٱلذين من دونهۦ ﴾ الزمر ٣٦ وقال تعالى ﴿ وٱلله على كل شيۡء وكيل ﴾ هود ١٢ والوكيل الكافي الكفيل وهو عام وخاص أما العام فهو المتكفل بأرزاق جميع المخلوقات وأقواتها القائم بتدبير شؤون الكائنات وتصريف أمورها وأما الخاص بعباده المؤمنين به المتوكلين عليه ففي قوله تعالى ﴿ وتوكلۡ على ٱللهۚ وكفى بٱلله وكيلا ﴾ النساء ٨١ أي نعم الكافي لمن التجأ إليه والحافظ لمن اعتصم به وهو المراد في قول المؤمنين ﴿ حسۡبنا ٱلله ونعۡم ٱلۡوكيل ﴾ آل عمران ١٧٣', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1575, 171, 10, 'والتوكُّل عمل القلب، والأخذ بالأسباب عملُ الجوارح، فلا يصحُّ التوكُّلُ إلَّا معَ القيام بالأسبابِ وعَدَمِ الإخلالِ بها، لكن من تمامه عدم الركون إلى الأسباب وقطع تعلُّق القلب بها، فيكون القلبُ منقطعًا منها متصلًا بالله تعالى، أمَّا الجوارحُ فتشتغِلُ بالأسبابِ، قال ﷺ: «اعقِلْها وتوكَّلْ»، وقال ﷺ: «لو تَوَكَّلْتُم على اللهِ حَقَّ تَوَكُّلِهِ لَرَزَقَكُم كَمَا تُرْزَقُ الطَّيرُ؛ تَغدو خِماصًا، وتَروحُ بِطانًا»، فهي لا تمكثُ في أعشاشها، ولكن تسعى لِرِزْقِها.', 0, 'النوع الحادي عشر: وِرْدُ الحَسْبَلة. (ص356)', '', '', 'والتوكل عمل القلب والأخذ بالأسباب عمل الجوارح فلا يصح التوكل إلا مع القيام بالأسباب وعدم الإخلال بها لكن من تمامه عدم الركون إلى الأسباب وقطع تعلق القلب بها فيكون القلب منقطعا منها متصلا بالله تعالى أما الجوارح فتشتغل بالأسباب قال «اعقلها وتوكل» وقال «لو توكلتم على الله حق توكله لرزقكم كما ترزق الطير تغدو خماصا وتروح بطانا» فهي لا تمكث في أعشاشها ولكن تسعى لرزقها', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1576, 172, 1, 'صيغ الحسبلة:', 0, '(ص357)', '', '', 'صيغ الحسبلة', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1577, 172, 2, '﴿ حَسۡبُنَا ٱللَّهُ وَنِعۡمَ ٱلۡوَكِيلُ ﴾', 1, 'صيغ الحسبلة. [آل عمران: ١٧٣]. (ص357)', '', '', '﴿ حسۡبنا ٱلله ونعۡم ٱلۡوكيل ﴾', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1578, 172, 3, '﴿ حَسۡبِيَ ٱللَّهُۖ عَلَيۡهِ يَتَوَكَّلُ ٱلۡمُتَوَكِّلُونَ ﴾', 1, 'صيغ الحسبلة. [الزمر: ٣٨]. (ص357)', '', '', '﴿ حسۡبي ٱللهۖ عليۡه يتوكل ٱلۡمتوكلون ﴾', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1579, 172, 4, '﴿ حَسۡبِيَ ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَۖ عَلَيۡهِ تَوَكَّلۡتُۖ وَهُوَ رَبُّ ٱلۡعَرۡشِ ٱلۡعَظِيمِ ﴾', 1, 'صيغ الحسبلة. [التوبة: ١٢٩]. (ص357)', '', '', '﴿ حسۡبي ٱلله لا إله إلا هوۖ عليۡه توكلۡتۖ وهو رب ٱلۡعرۡش ٱلۡعظيم ﴾', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1580, 172, 5, 'حسبي الله ونعم الوكيل.', 1, 'صيغ الحسبلة. (ص357)', '', '', 'حسبي الله ونعم الوكيل', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1581, 172, 6, 'ويقرب من هذه الصيغ:', 0, 'صيغ الحسبلة. (ص357)', '', '', 'ويقرب من هذه الصيغ', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1582, 172, 7, '﴿ هُوَ رَبِّي لَآ إِلَٰهَ إِلَّا هُوَ عَلَيۡهِ تَوَكَّلۡتُ وَإِلَيۡهِ مَتَابِ ﴾', 1, 'ويقرب من هذه الصيغ. [الرعد: ٣٠]. (ص357)', '', '', '﴿ هو ربي لا إله إلا هو عليۡه توكلۡت وإليۡه متاب ﴾', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1583, 172, 8, '﴿ وَمَا تَوۡفِيقِيٓ إِلَّا بِٱللَّهِۚ عَلَيۡهِ تَوَكَّلۡتُ وَإِلَيۡهِ أُنِيبُ ﴾', 1, 'ويقرب من هذه الصيغ. [هود: ٨٨]. (ص357)', '', '', '﴿ وما توۡفيقي إلا بٱللهۚ عليۡه توكلۡت وإليۡه أنيب ﴾', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1584, 172, 9, '﴿ رَّبَّنَا عَلَيۡكَ تَوَكَّلۡنَا وَإِلَيۡكَ أَنَبۡنَا وَإِلَيۡكَ ٱلۡمَصِيرُ ﴾', 1, 'ويقرب من هذه الصيغ. [الممتحنة: ٤]. (ص357)', '', '', '﴿ ربنا عليۡك توكلۡنا وإليۡك أنبۡنا وإليۡك ٱلۡمصير ﴾', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1585, 172, 10, '﴿ وَأُفَوِّضُ أَمۡرِيٓ إِلَى ٱللَّهِۚ إِنَّ ٱللَّهَ بَصِيرُۢ بِٱلۡعِبَادِ ﴾', 1, 'ويقرب من هذه الصيغ. [غافر: ٤٤]. (ص357)', '', '', '﴿ وأفوض أمۡري إلى ٱللهۚ إن ٱلله بصيرۢ بٱلۡعباد ﴾', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1586, 174, 1, 'النوع الثاني عشر: وِرْدُ الدعاء للوالدين في حياتهما وبعدَ موتهما', 0, '(ص358)', '', '', 'النوع الثاني عشر ورد الدعاء للوالدين في حياتهما وبعد موتهما', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1587, 174, 2, 'الدعاء للوالدين في حياتهما وبعد موتهما من أعظمِ صُوَرِ بِرِّهما، وقد دعا الأنبياء عليهم السلام لوالدِيهم، فقال نوح عليه السلام: ﴿ رَّبِّ ٱغۡفِرۡ لِي وَلِوَٰلِدَيَّ ﴾ الآية [نوح: ٢٨]، ودعا إبراهيم عليه السلام لأبيه قبل أن يُنهَى عن الدعاء له: ﴿ وَٱغۡفِرۡ لِأَبِيٓ ﴾ الآية [الشعراء: ٨٦]، وقد قال تعالى لخليله محمدٍ ﷺ: ﴿ أُوْلَٰٓئِكَ ٱلَّذِينَ هَدَى ٱللَّهُۖ فَبِهُدَىٰهُمُ ٱقۡتَدِهۡ ﴾ [الأنعام: ٩٠]، وأَمْرُ القدوةِ أَمْرٌ لأتباعه.', 0, 'النوع الثاني عشر: وِرْدُ الدعاء للوالدين في حياتهما وبعدَ موتهما. (ص358)', '', '', 'الدعاء للوالدين في حياتهما وبعد موتهما من أعظم صور برهما وقد دعا الأنبياء عليهم السلام لوالديهم فقال نوح عليه السلام ﴿ رب ٱغۡفرۡ لي ولولدي ﴾ الآية نوح ٢٨ ودعا إبراهيم عليه السلام لأبيه قبل أن ينهى عن الدعاء له ﴿ وٱغۡفرۡ لأبي ﴾ الآية الشعراء ٨٦ وقد قال تعالى لخليله محمد ﴿ أولئك ٱلذين هدى ٱللهۖ فبهدىهم ٱقۡتدهۡ ﴾ الأنعام ٩٠ وأمر القدوة أمر لأتباعه', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1588, 174, 3, 'وفي سياق أمر الأولاد بالإحسان إلى الوالدَيْنِ قال الله تعالى: ﴿ وَقُل رَّبِّ ٱرۡحَمۡهُمَا كَمَا رَبَّيَانِي صَغِيرٗا ﴾ [الإسراء: ٢٤].', 0, 'النوع الثاني عشر: وِرْدُ الدعاء للوالدين في حياتهما وبعدَ موتهما. (ص358)', '', '', 'وفي سياق أمر الأولاد بالإحسان إلى الوالدين قال الله تعالى ﴿ وقل رب ٱرۡحمۡهما كما ربياني صغيرا ﴾ الإسراء ٢٤', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1589, 174, 4, 'قال العلامة الطاهر بن عاشور رحمه الله: «في الآية الكريمة إيماءٌ إلى أنَّ الدعاءَ للوالدَيْنِ مُستجاب؛ لأن الله أَذِنَ فيه».', 0, 'النوع الثاني عشر: وِرْدُ الدعاء للوالدين في حياتهما وبعدَ موتهما. (ص358)', '', '', 'قال العلامة الطاهر بن عاشور رحمه الله «في الآية الكريمة إيماء إلى أن الدعاء للوالدين مستجاب لأن الله أذن فيه»', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1590, 174, 5, 'وعن أبي هريرة رضي الله عنه، أن رسول الله ﷺ قال: «إذا مات الإنسانُ انقطع عملُه إلا من ثلاثٍ: صدقةٍ جاريةٍ، أو علمٍ يُنْتَفَعُ به، أو ولدٍ صالحٍ يدعو له».', 0, 'النوع الثاني عشر: وِرْدُ الدعاء للوالدين في حياتهما وبعدَ موتهما. (ص359)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1591, 174, 6, 'وعن أبي هريرة رضي الله عنه، قال رسول الله ﷺ: «تُرفَع للميتِ بعدَ مَوتِهِ درجةٌ، فيقول: أَيْ رَبِّ، أيُّ شيءٍ هذه؟ فيُقال: ولدُكَ استَغْفَرَ لَكَ». أو «باستغفارِ ولدِكَ لك»، وفي رواية: «بدعاءِ وَلَدِكَ لك».', 0, 'النوع الثاني عشر: وِرْدُ الدعاء للوالدين في حياتهما وبعدَ موتهما. (ص359)', '', '', 'وعن أبي هريرة رضي الله عنه قال رسول الله «ترفع للميت بعد موته درجة فيقول أي رب أي شيء هذه فيقال ولدك استغفر لك» أو «باستغفار ولدك لك» وفي رواية «بدعاء ولدك لك»', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1592, 174, 7, 'ولقد كانَ السَّلَفُ الصَّالحُ رحمهم الله يواظِبونَ على الدُّعاءِ للوالدين:', 0, 'النوع الثاني عشر: وِرْدُ الدعاء للوالدين في حياتهما وبعدَ موتهما. (ص359)', '', '', 'ولقد كان السلف الصالح رحمهم الله يواظبون على الدعاء للوالدين', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1593, 174, 8, 'فعن عامر بن عبد الله بن الزبير قال: «مات أبي، فما سألتُ اللهَ -حَوْلًا- إلا العفوَ عنه».', 0, 'ولقد كانَ السَّلَفُ الصَّالحُ رحمهم الله يواظِبونَ على الدُّعاءِ للوالدين. (ص359)', '', '', 'فعن عامر بن عبد الله بن الزبير قال «مات أبي فما سألت الله -حولا- إلا العفو عنه»', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1594, 174, 9, 'وكان عروة بن الزبير يقول في صلاته -وهو ساجد-: «اللهم اغفر للزبير بن العوام، وأسماءَ بنتِ أبي بكر» يعني: والديه رضي الله عنهما.', 0, 'ولقد كانَ السَّلَفُ الصَّالحُ رحمهم الله يواظِبونَ على الدُّعاءِ للوالدين. (ص359)', '', '', 'وكان عروة بن الزبير يقول في صلاته -وهو ساجد- «اللهم اغفر للزبير بن العوام وأسماء بنت أبي بكر» يعني والديه رضي الله عنهما', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1595, 174, 10, 'وكان الإمام أبو حنيفة رحمه الله بَرًّا بوالديه، وكان يدعو لهما، ويستغفر لهما مع شيخه حماد، وكان يتصدق كل شهر بعشرين دينارًا عن والديه.', 0, 'ولقد كانَ السَّلَفُ الصَّالحُ رحمهم الله يواظِبونَ على الدُّعاءِ للوالدين. (ص360)', '', '', 'وكان الإمام أبو حنيفة رحمه الله برا بوالديه وكان يدعو لهما ويستغفر لهما مع شيخه حماد وكان يتصدق كل شهر بعشرين دينارا عن والديه', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1596, 174, 11, 'وكان أبو يوسفَ الفقيهُ يقول عَقِيبَ صلاتِه: «اللهم اغفِرْ لأبويَّ، ولأبي حنيفة».', 0, 'ولقد كانَ السَّلَفُ الصَّالحُ رحمهم الله يواظِبونَ على الدُّعاءِ للوالدين. (ص360)', '', '', 'وكان أبو يوسف الفقيه يقول عقيب صلاته «اللهم اغفر لأبوي ولأبي حنيفة»', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1597, 175, 1, 'صيغة الدعاء للوالدين:', 0, '(ص361)', '', '', 'صيغة الدعاء للوالدين', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1598, 175, 2, 'من البر بالوالدين أن يخصهما الولد بورد «شخصي» يُمَحِّضُ فيه الدعاء لهما، ويكرره بالعدد الذي يناسبه.', 0, 'صيغة الدعاء للوالدين. (ص361)', '', '', 'من البر بالوالدين أن يخصهما الولد بورد «شخصي» يمحض فيه الدعاء لهما ويكرره بالعدد الذي يناسبه', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1599, 175, 3, 'وأفضل صيغة للدعاء للوالدين ما جاء في كلام الملك عَزَّ وَجَلَّ الذي هو مَلِكُ الكلام؛ كأن يقول:', 0, 'صيغة الدعاء للوالدين. (ص361)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1600, 175, 4, '﴿ رَّبِّ ٱغۡفِرۡ لِي وَلِوَٰلِدَيَّ وَلِمَن دَخَلَ بَيۡتِيَ مُؤۡمِنٗا وَلِلۡمُؤۡمِنِينَ وَٱلۡمُؤۡمِنَٰتِ ﴾', 1, 'صيغة الدعاء للوالدين. [نوح: ٢٨]. (ص361)', '', '', '﴿ رب ٱغۡفرۡ لي ولولدي ولمن دخل بيۡتي مؤۡمنا وللۡمؤۡمنين وٱلۡمؤۡمنت ﴾', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1601, 175, 5, 'QuranText[(14:41:41)]', 1, 'صيغة الدعاء للوالدين. [إبراهيم: ٤١]. (ص361)', '', '', '144141', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1602, 175, 6, '﴿ رَّبِّ ٱرۡحَمۡهُمَا كَمَا رَبَّيَانِي صَغِيرٗا ﴾', 1, 'صيغة الدعاء للوالدين. [الإسراء: ٢٤]. (ص361)', '', '', '﴿ رب ٱرۡحمۡهما كما ربياني صغيرا ﴾', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1603, 177, 1, 'النوع الثالث عشر: التعوُّذات', 0, '(ص362)', '', '', 'النوع الثالث عشر التعوذات', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1604, 177, 2, 'التعوذات من أهم الأذكار التي يحتاج إليها كل مسلمٍ حمايةً لنفسه وأهله وولدِه ومالِه وسائرِ ما يتعلق به؛ من الشرور الظاهرة والباطنة، في كل أوقاته وأحواله، في الدنيا والبرزخ والآخرة.', 0, 'النوع الثالث عشر: التعوُّذات. (ص362)', '', '', 'التعوذات من أهم الأذكار التي يحتاج إليها كل مسلم حماية لنفسه وأهله وولده وماله وسائر ما يتعلق به من الشرور الظاهرة والباطنة في كل أوقاته وأحواله في الدنيا والبرزخ والآخرة', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1605, 177, 3, 'وقد قال الله تعالى: ﴿ لَقَدۡ جَآءَكُمۡ رَسُولٞ مِّنۡ أَنفُسِكُمۡ عَزِيزٌ عَلَيۡهِ مَا عَنِتُّمۡ حَرِيصٌ عَلَيۡكُم بِٱلۡمُؤۡمِنِينَ رَءُوفٞ رَّحِيمٞ ﴾ [التوبة: ١٢٨].', 0, 'النوع الثالث عشر: التعوُّذات. (ص362)', '', '', 'وقد قال الله تعالى ﴿ لقدۡ جاءكمۡ رسول منۡ أنفسكمۡ عزيز عليۡه ما عنتمۡ حريص عليۡكم بٱلۡمؤۡمنين رءوف رحيم ﴾ التوبة ١٢٨', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1606, 177, 4, 'وعن عبد الله بن عمرو رضي الله عنهما قال رسول الله صَلَّى اللهُ عَلَيْهِ وَآلِهِ وَسَلَّمَ: «إنه لم يكن نبيٌّ قبلي إلا كان حقًّا عليه أن يَدُلَّ أمتَه على خيرِ ما يعلمُه لهم، وينذرَهم شَرَّ ما يعلمُه لهم».', 0, 'النوع الثالث عشر: التعوُّذات. (ص362)', '', '', 'وعن عبد الله بن عمرو رضي الله عنهما قال رسول الله صلى الله عليه وآله وسلم «إنه لم يكن نبي قبلي إلا كان حقا عليه أن يدل أمته على خير ما يعلمه لهم وينذرهم شر ما يعلمه لهم»', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1607, 177, 5, 'الاستعاذة لغةً:', 0, 'النوع الثالث عشر: التعوُّذات. (ص363)', '', '', 'الاستعاذة لغة', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1608, 177, 6, 'مصدر استعاذ من مادة (ع و ذ) التي تدل على التحرُّز والتحصُّن والنجاة بالالتجاء إلى الشيء، والاعتصام به للامتناع عن المكروه.', 0, 'الاستعاذة لغةً. (ص363)', '', '', 'مصدر استعاذ من مادة ع و ذ التي تدل على التحرز والتحصن والنجاة بالالتجاء إلى الشيء والاعتصام به للامتناع عن المكروه', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1609, 177, 7, 'الاستعاذة اصطلاحًا:', 0, 'الاستعاذة لغةً. (ص363)', '', '', 'الاستعاذة اصطلاحا', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1610, 177, 8, 'هي اللجوء إلى الله تعالى وحدَه، والاعتصامُ به وبأسمائه وصفاته وكلماته، من شَرِّ كلِّ ذِي شَرٍّ.', 0, 'الاستعاذة اصطلاحًا. (ص363)', '', '', 'هي اللجوء إلى الله تعالى وحده والاعتصام به وبأسمائه وصفاته وكلماته من شر كل ذي شر', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1611, 177, 9, 'وأصول الاستعاذة ثلاثة: مُسْتَعاذٌ به، ومستعاذٌ منه، وصيغةٌ.', 0, 'الاستعاذة اصطلاحًا. (ص363)', '', '', 'وأصول الاستعاذة ثلاثة مستعاذ به ومستعاذ منه وصيغة', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1612, 177, 10, 'والله سبحانه وتعالى وحده هو المَعاذ والمستعاذ به، قال تعالى: ﴿ إِنَّ ٱللَّهَ يُدَٰفِعُ عَنِ ٱلَّذِينَ ءَامَنُوٓاْ ﴾ [الحج: ٣٨]، وفي قراءة: ﴿ يَدۡفَعُ ﴾، وقال سبحانه: ﴿ أَلَيۡسَ ٱللَّهُ بِكَافٍ عَبۡدَهُۥ ﴾ [الزمر: ٣٦]، وفي قراءة: ﴿ عِبادَهُ ﴾.', 0, 'الاستعاذة اصطلاحًا. (ص363)', '', '', 'والله سبحانه وتعالى وحده هو المعاذ والمستعاذ به قال تعالى ﴿ إن ٱلله يدفع عن ٱلذين ءامنوا ﴾ الحج ٣٨ وفي قراءة ﴿ يدۡفع ﴾ وقال سبحانه ﴿ أليۡس ٱلله بكاف عبۡدهۥ ﴾ الزمر ٣٦ وفي قراءة ﴿ عباده ﴾', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1613, 177, 11, 'وتكون الاستعاذة بالله سبحانه كما في قوله تعالى: ﴿ فَٱسۡتَعِذۡ بِٱللَّهِ مِنَ ٱلشَّيۡطَٰنِ ٱلرَّجِيمِ ﴾ [النحل: ٩٨]، وكما في حديثِ الوَلِي: «ولَئِن استعاذَ بي لأُعِيذَنَّه»، .', 0, 'الاستعاذة اصطلاحًا. (ص364)', '', '', 'وتكون الاستعاذة بالله سبحانه كما في قوله تعالى ﴿ فٱسۡتعذۡ بٱلله من ٱلشيۡطن ٱلرجيم ﴾ النحل ٩٨ وكما في حديث الولي «ولئن استعاذ بي لأعيذنه»', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1614, 177, 12, 'وقد كثر في القرآن الكريم تعوُّذُ الأنبياءِ والصالحينَ بالله عَزَّ وَجَلَّ؛ ومن ذلك:', 0, 'الاستعاذة اصطلاحًا. (ص364)', '', '', 'وقد كثر في القرآن الكريم تعوذ الأنبياء والصالحين بالله عز وجل ومن ذلك', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1615, 177, 13, 'تعوُّذُ موسى عليه السلام: ﴿ وَقَالَ مُوسَىٰٓ إِنِّي عُذۡتُ بِرَبِّي وَرَبِّكُم مِّن كُلِّ مُتَكَبِّرٖ لَّا يُؤۡمِنُ بِيَوۡمِ ٱلۡحِسَابِ ﴾ [غافر: ٢٧]، ﴿ وَإِنِّي عُذۡتُ بِرَبِّي وَرَبِّكُمۡ أَن تَرۡجُمُونِ ﴾ [الدخان: ٢٠].', 0, 'الاستعاذة اصطلاحًا. (ص364)', '', '', 'تعوذ موسى عليه السلام ﴿ وقال موسى إني عذۡت بربي وربكم من كل متكبر لا يؤۡمن بيوۡم ٱلۡحساب ﴾ غافر ٢٧ ﴿ وإني عذۡت بربي وربكمۡ أن ترۡجمون ﴾ الدخان ٢٠', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1616, 177, 14, 'ومنه تعوُّذُ أمِّ مريمَ عليها السلام: ﴿ وَإِنِّيٓ أُعِيذُهَا بِكَ وَذُرِّيَّتَهَا مِنَ ٱلشَّيۡطَٰنِ ٱلرَّجِيمِ ﴾ [آل عمران: ٣٦].', 0, 'الاستعاذة اصطلاحًا. (ص364)', '', '', 'ومنه تعوذ أم مريم عليها السلام ﴿ وإني أعيذها بك وذريتها من ٱلشيۡطن ٱلرجيم ﴾ آل عمران ٣٦', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1617, 177, 15, 'وتعوُّذُ مريمَ عليها السلام: ﴿ قَالَتۡ إِنِّيٓ أَعُوذُ بِٱلرَّحۡمَٰنِ مِنكَ إِن كُنتَ تَقِيّٗا ﴾ [مريم: ١٨].', 0, 'الاستعاذة اصطلاحًا. (ص364)', '', '', 'وتعوذ مريم عليها السلام ﴿ قالتۡ إني أعوذ بٱلرحۡمن منك إن كنت تقيا ﴾ مريم ١٨', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1618, 177, 16, 'ومنه أمرُ الله نبيَّه وخليلَه محمدًا صَلَّى اللهُ عَلَيْهِ وَآلِهِ وَسَلَّمَ: ﴿ وَقُل رَّبِّ أَعُوذُ بِكَ مِنۡ هَمَزَٰتِ ٱلشَّيَٰطِينِ ۝ وَأَعُوذُ بِكَ رَبِّ أَن يَحۡضُرُونِ ﴾ [المؤمنون: ٩٧، ٩٨].', 0, 'الاستعاذة اصطلاحًا. (ص364)', '', '', 'ومنه أمر الله نبيه وخليله محمدا صلى الله عليه وآله وسلم ﴿ وقل رب أعوذ بك منۡ همزت ٱلشيطين ۝ وأعوذ بك رب أن يحۡضرون ﴾ المؤمنون ٩٧ ٩٨', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1619, 177, 17, 'ومن التعوُّذِ بصفاتِ الله سبحانه: قولُ رسولِ الله ﷺ: «اللهم إني أعوذُ برضاك من سَخَطِك، وبمعافاتك من عقوبتك» الحديث.', 0, 'الاستعاذة اصطلاحًا. (ص365)', '', '', 'ومن التعوذ بصفات الله سبحانه قول رسول الله «اللهم إني أعوذ برضاك من سخطك وبمعافاتك من عقوبتك» الحديث', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1620, 177, 18, 'وأَمَرَ ﷺ رجلًا مريضًا بأنْ يقولَ سبعَ مرَّاتٍ: «أعوذُ بعِزَّةِ اللهِ وقُدْرَتِه من شَرِّ ما أَجِدُ وأُحاذِرُ».', 0, 'الاستعاذة اصطلاحًا. (ص365)', '', '', 'وأمر رجلا مريضا بأن يقول سبع مرات «أعوذ بعزة الله وقدرته من شر ما أجد وأحاذر»', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1621, 177, 19, 'وعن ابنِ عبَّاسٍ رضي الله عنهما قال: كان النبيُّ ﷺ يُعَوِّذُ الحسنَ والحسينَ ويقول: «إنَّ أباكما إبراهيمَ كان يُعَوِّذُ بها إسماعيلَ وإسحاقَ: أُعيذُكُما بكلماتِ الله التَّامَّةِ من كلِّ شيطانٍ وهامَّةٍ، ومن كُلِّ عينٍ لامَّةٍ».', 0, 'الاستعاذة اصطلاحًا. (ص365)', '', '', 'وعن ابن عباس رضي الله عنهما قال كان النبي يعوذ الحسن والحسين ويقول «إن أباكما إبراهيم كان يعوذ بها إسماعيل وإسحاق أعيذكما بكلمات الله التامة من كل شيطان وهامة ومن كل عين لامة»', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1622, 177, 20, 'والمُستعاذ منه: هو ما يُصِيبُ الإنسانَ من شَرٍّ.', 0, 'الاستعاذة اصطلاحًا. (ص365)', '', '', 'والمستعاذ منه هو ما يصيب الإنسان من شر', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1623, 177, 21, 'قال الإمام المحقق ابن قَيِّمِ الجوزيَّةِ رحمه الله: «الشَّرُّ يُقَالُ على شيئين: على الألم، وعلى ما يُفضي إليه. وليس له مسمًّى سوى ذلك، فالشرور: هي الآلام وأسبابها. فالمعاصي والكفر والشرك وأنواع الظلم هي شرور، وإن كان لصاحبها فيها نوعُ غرضٍ ولذَّةٍ، لكنها شرور؛ لأنها أسبابٌ للآلام، ومُفْضِيَةٌ إليها، كإفضاء سائر الأسباب إلى مُسَبَّباتِها، فترتُّب الألم عليها كترتب الموت على تناول السموم القاتلة، وعلى الذبح، والإحراقِ بالنار، والخنق بالحبل، وغيرِ ذلك من الأسباب التي تكون مفضية إلى مسبباتها، ولا بُدَّ، ما لم يمنع من السببية مانع، أو يعارض السببَ ما هو أقوى منه وأشدُّ اقتضاءً لضده، كما يعارض سببَ المعاصي قوةُ الإيمان، وعِظَمُ الحسناتِ الماحية وكثرتُها، فيزيد في كميتها أو كيفيتها على أسباب العذاب فيدفع الأقوى الأضعفَ».', 0, 'الاستعاذة اصطلاحًا. (ص365–366)', '', '', 'قال الإمام المحقق ابن قيم الجوزية رحمه الله «الشر يقال على شيئين على الألم وعلى ما يفضي إليه وليس له مسمى سوى ذلك فالشرور هي الآلام وأسبابها فالمعاصي والكفر والشرك وأنواع الظلم هي شرور وإن كان لصاحبها فيها نوع غرض ولذة لكنها شرور لأنها أسباب للآلام ومفضية إليها كإفضاء سائر الأسباب إلى مسبباتها فترتب الألم عليها كترتب الموت على تناول السموم القاتلة وعلى الذبح والإحراق بالنار والخنق بالحبل وغير ذلك من الأسباب التي تكون مفضية إلى مسبباتها ولا بد ما لم يمنع من السببية مانع أو يعارض السبب ما هو أقوى منه وأشد اقتضاء لضده كما يعارض سبب المعاصي قوة الإيمان وعظم الحسنات الماحية وكثرتها فيزيد في كميتها أو كيفيتها على أسباب العذاب فيدفع الأقوى الأضعف»', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1624, 177, 22, 'وأما كون ما تُفْضِي إليه أسبابُ الآلام شرورًا؛ فلأنها آلام نفسية وبدنية، فيجتمع على صاحبها مع شدة الألم الحسي، ألمُ الروحِ بالهموم والغموم والأحزان والحسرات.', 0, 'الاستعاذة اصطلاحًا. (ص366)', '', '', 'وأما كون ما تفضي إليه أسباب الآلام شرورا فلأنها آلام نفسية وبدنية فيجتمع على صاحبها مع شدة الألم الحسي ألم الروح بالهموم والغموم والأحزان والحسرات', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1625, 178, 1, 'التعوُّذ في السُّنَّةِ الشَّريفة', 0, '(ص367)', '', '', 'التعوذ في السنة الشريفة', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1626, 178, 2, 'لقد حفلت السنة النبوية الشريفة القولية والعملية بقدرٍ وافرٍ من كنوز التعويذات النبوية المباركة، وفصَّلتْ أنواعَ الشرور التي ينبغي الاستعاذةُ منها:', 0, 'التعوُّذ في السُّنَّةِ الشَّريفة. (ص367)', '', '', 'لقد حفلت السنة النبوية الشريفة القولية والعملية بقدر وافر من كنوز التعويذات النبوية المباركة وفصلت أنواع الشرور التي ينبغي الاستعاذة منها', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1627, 178, 3, 'في كل الأوقات والأحوال: من ليل أو نهار، وصباح ومساء، وعند النوم واليقظة، وفي السراء والضراء، والرضى والغضب، والغِنى والفقر، والصحة والمرض، في الطفولة والشباب، والشيخوخة والهَرَمِ وأرذلِ العُمُر.', 0, 'التعوُّذ في السُّنَّةِ الشَّريفة. (ص367)', '', '', 'في كل الأوقات والأحوال من ليل أو نهار وصباح ومساء وعند النوم واليقظة وفي السراء والضراء والرضى والغضب والغنى والفقر والصحة والمرض في الطفولة والشباب والشيخوخة والهرم وأرذل العمر', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1628, 178, 4, 'ومن شرِّ كُلِّ ذي شَرٍّ من المخلوقات: كإبليسَ وجنودِه، وشياطينِ الجنِّ والإنسِ، والحاسدين، والظالمين، والسَّحَرَةِ، وأصحابِ الأهواء والبدع، وجيرانِ السُّوءِ وأصحابِ السُّوء.', 0, 'التعوُّذ في السُّنَّةِ الشَّريفة. (ص367)', '', '', 'ومن شر كل ذي شر من المخلوقات كإبليس وجنوده وشياطين الجن والإنس والحاسدين والظالمين والسحرة وأصحاب الأهواء والبدع وجيران السوء وأصحاب السوء', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1629, 178, 5, 'بل من شرور أنفسِنا وأهوائنا ومنكراتِ أخلاقنا، من حَواسِّنا وأعضائنا؛ كالقلب والعين واللسان والأذنِ والفَرْجِ، من أموالنا، وسيئاتِ أعمالنا؛ ما وقع منها بالفعل، وما نخافُ وقوعَه ونحذرُه.', 0, 'التعوُّذ في السُّنَّةِ الشَّريفة. (ص368)', '', '', 'بل من شرور أنفسنا وأهوائنا ومنكرات أخلاقنا من حواسنا وأعضائنا كالقلب والعين واللسان والأذن والفرج من أموالنا وسيئات أعمالنا ما وقع منها بالفعل وما نخاف وقوعه ونحذره', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1630, 178, 6, 'من المصائب والأقدار المؤلمة؛ كالحروب، والأوبئة، والأمراض الجسدية والنفسية.', 0, 'التعوُّذ في السُّنَّةِ الشَّريفة. (ص368)', '', '', 'من المصائب والأقدار المؤلمة كالحروب والأوبئة والأمراض الجسدية والنفسية', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1631, 178, 7, 'من الفتن ما ظهر منها وما بطن: لا سيما في عصر غُرْبَةِ الإسلام، وَفِتَنِ آخِرِ الزمان؛ كالدعاةِ على أبوابِ جهنمَ، وفتنةِ المسيح الدجال «شَرِّ غَائِبٍ يُنتَظَرُ».', 0, 'التعوُّذ في السُّنَّةِ الشَّريفة. (ص368)', '', '', 'من الفتن ما ظهر منها وما بطن لا سيما في عصر غربة الإسلام وفتن آخر الزمان كالدعاة على أبواب جهنم وفتنة المسيح الدجال «شر غائب ينتظر»', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1632, 178, 8, 'ومن مصارع السُّوءِ: كالهدم والتردِّي والغَرَقِ والحَرَقِ والزلزالِ والخسف، ومن سُوء الخاتمة عند الاحتضار، وتخبطِ الشيطان عند الموت، ومن عذاب القبر في الحياة البرزخية، ومن فتنِ وأهوالِ يومِ القيامة، وعذاب جهنمَ، أعاذنا الله منها ومن سائر الشرور.', 0, 'التعوُّذ في السُّنَّةِ الشَّريفة. (ص368)', '', '', 'ومن مصارع السوء كالهدم والتردي والغرق والحرق والزلزال والخسف ومن سوء الخاتمة عند الاحتضار وتخبط الشيطان عند الموت ومن عذاب القبر في الحياة البرزخية ومن فتن وأهوال يوم القيامة وعذاب جهنم أعاذنا الله منها ومن سائر الشرور', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1633, 179, 1, 'التعوُّذات موظَّفة ومُطلَقة', 0, '(ص369)', '', '', 'التعوذات موظفة ومطلقة', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1634, 179, 2, 'أمَّا التعوذات الموظفة:', 0, 'التعوُّذات موظَّفة ومُطلَقة. (ص369)', '', '', 'أما التعوذات الموظفة', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1635, 179, 3, 'فهي المقيدة بوظيفة أو وقتٍ أو حالٍ: كبعضِ أذكارِ الصباحِ والمساء والنوم، ودخولِ الخلاء، والخروج من البيت، ودخول المسجد، وقبل التشهُّد، وبعد الصلاة، والرقية، وغيرِها مما هو مبثوثٌ في هذا الكتاب.', 0, 'أمَّا التعوذات الموظفة. (ص369)', '', '', 'فهي المقيدة بوظيفة أو وقت أو حال كبعض أذكار الصباح والمساء والنوم ودخول الخلاء والخروج من البيت ودخول المسجد وقبل التشهد وبعد الصلاة والرقية وغيرها مما هو مبثوث في هذا الكتاب', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1636, 179, 4, 'وأمَّا التعوذات المطلقة:', 0, 'أمَّا التعوذات الموظفة. (ص369)', '', '', 'وأما التعوذات المطلقة', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1637, 179, 5, 'فهي التي لم تُقَيَّدْ بوظيفةٍ أو وقتٍ أو حالٍ.', 0, 'وأمَّا التعوذات المطلقة. (ص369)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1638, 179, 6, 'أفضلُ ما يُتَعَوَّذُ به:', 0, 'وأمَّا التعوذات المطلقة. (ص370)', '', '', 'أفضل ما يتعوذ به', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1639, 179, 7, 'عن ابن عابسٍ الجُهَني -وهو عقبة بن عامر- رضي الله عنه أنَّ رسول الله ﷺ قال له: «يا بن عابس، ألا أدُلُّكَ؟» أو قال: «ألا أخبرك بأفضلِ ما يتعوَّذُ به المتعوِّذون؟»، قال: بلى يا رسول الله، قال: ﴿ قُلۡ أَعُوذُ بِرَبِّ ٱلۡفَلَقِ ﴾، ﴿ قُلۡ أَعُوذُ بِرَبِّ ٱلنَّاسِ ﴾ هاتين السورتين»، وقال له النبيُّ ﷺ: «ما سألَ سائلٌ بمثلهما، ولا استعاذَ مُستعيذٌ بمثلهما».', 0, 'أفضلُ ما يُتَعَوَّذُ به. (ص370)', '', '', 'عن ابن عابس الجهني -وهو عقبة بن عامر- رضي الله عنه أن رسول الله قال له «يا بن عابس ألا أدلك » أو قال «ألا أخبرك بأفضل ما يتعوذ به المتعوذون » قال بلى يا رسول الله قال ﴿ قلۡ أعوذ برب ٱلۡفلق ﴾ ﴿ قلۡ أعوذ برب ٱلناس ﴾ هاتين السورتين» وقال له النبي «ما سأل سائل بمثلهما ولا استعاذ مستعيذ بمثلهما»', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1640, 179, 8, 'وعن أبي سعيدٍ الخدري رضي الله عنه قال: «كان رسولُ الله ﷺ يتعوَّذُ من عين الجانِّ وعينِ الإنسِ، فلمَّا نزلَتِ المُعوِّذتان أخذ بهما، وتَرَكَ ما سوى ذلك».', 0, 'أفضلُ ما يُتَعَوَّذُ به. (ص370)', '', '', 'وعن أبي سعيد الخدري رضي الله عنه قال «كان رسول الله يتعوذ من عين الجان وعين الإنس فلما نزلت المعوذتان أخذ بهما وترك ما سوى ذلك»', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1641, 179, 9, 'وسبب ذلك؛ أنَّ هاتين السورتين قد تضمَّنتا الاستعاذة من الشرور كُلِّها بأوجزِ لفظٍ وأجمعِه، وأدلِّه على المراد، وأعمِّه استعاذةً، بحيثُ لم يبقَ من شَرٍّ من الشرور إلَّا دَخَلَ تحت المستعاذ منه فيهما.', 0, 'أفضلُ ما يُتَعَوَّذُ به. (ص370)
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1642, 179, 10, 'حكم التعوُّذِ من أربعٍ بَعْدَ التَّشهُّدِ الذي يعقُبه التسليمُ:', 0, 'أفضلُ ما يُتَعَوَّذُ به. (ص371)', '', '', 'حكم التعوذ من أربع بعد التشهد الذي يعقبه التسليم', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1643, 179, 11, 'ثبت الأمر به في حديث أبي هريرة رضي الله عنه أن النبي ﷺ قال: «إذا فرغ أحدُكم من التشهد فليتعوَّذْ بالله من أربعٍ: من عذابِ جهنمَ، ومن عذابِ القبرِ، ومن فتنةِ المَحْيا والمَماتِ، ومن شَرِّ فتنةِ المسيحِ الدجال».', 0, 'حكم التعوُّذِ من أربعٍ بَعْدَ التَّشهُّدِ الذي يعقُبه التسليمُ. (ص371)', '', '', 'ثبت الأمر به في حديث أبي هريرة رضي الله عنه أن النبي قال «إذا فرغ أحدكم من التشهد فليتعوذ بالله من أربع من عذاب جهنم ومن عذاب القبر ومن فتنة المحيا والممات ومن شر فتنة المسيح الدجال»', '', '');
INSERT INTO contents (id, titleId, "order", body, count, source, hokm, fadl, search, sourceIndex, style) VALUES (1644, 179, 12, 'والظاهر أن هذا التعوذ سنة مؤكدة تأكيدًا شديدًا؛ لأن النبي ﷺ أمر به، وفَعَلَه، والله تعالى أعلم.', 0, 'حكم التعوُّذِ من أربعٍ بَعْدَ التَّشهُّدِ الذي يعقُبه التسليمُ. (ص371)
